SELECT "MulheresMil_1"."no_modalidade" AS "no_modalidade",   "MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" AS "nome_da_sit_matricula__situacao_detalhada_",   SUM(CAST("MulheresMil_1"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   CAST(EXTRACT(YEAR FROM "MulheresMil_1"."data_de_inicio") AS BIGINT) AS "yr_data_de_inicio_ok" FROM "MulheresMil_1" WHERE (("MulheresMil_1"."no_modalidade" IN ('pronatec turismo cidadão', 'Pronatec turismo Desenvolvimento Local', 'PRONATEC TURISMO na EMPRESA', 'PRONATEC TURISMO SOCIAL')) AND (NOT (("MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR ("MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND ((CAST(EXTRACT(YEAR FROM "MulheresMil_1"."data_de_inicio") AS BIGINT) IS NULL) OR ((CAST(EXTRACT(YEAR FROM "MulheresMil_1"."data_de_inicio") AS BIGINT) >= 1201) AND (CAST(EXTRACT(YEAR FROM "MulheresMil_1"."data_de_inicio") AS BIGINT) <= 3013))) AND (NOT ("MulheresMil_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY "MulheresMil_1"."no_modalidade",   "MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_", "yr_data_de_inicio_ok";
